-- Уточнения в 8 вопросах раздела 18 «Память процесса» по повторной проверке.
-- Источник: scripts/questions/036_process_memory_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Функцию вызывают миллион раз в долго работающем процессе, все вызовы malloc успешны. Что произойдёт с его памятью?
```
void handle(void)
{
    char *tmp = malloc(1000);
    strcpy(tmp, "запрос");
}
```', NULL, NULL, NULL, 'Функцию вызывают миллион раз в долго работающем процессе. Программа собрана без оптимизации (-O0), все вызовы malloc успешны. Что произойдёт с его памятью?
```
void handle(void)
{
    char *tmp = malloc(1000);
    strcpy(tmp, "запрос");
}
```'),
        ('option', 'Программа печатает адреса строки исходного окружения, локальной переменной main, небольшого блока из malloc, глобальной переменной и функции main. В каком порядке они обычно идут в Linux на x86-64 при обычной сборке, от больших адресов к меньшим?', 'Стек, окружение, куча, код, данные', NULL, 'Окружение лежит над стеком, а данные — над кодом.', 'Исходное окружение лежит в верхней части начального стека, выше текущих кадров функций; данные обычно расположены выше кода.'),
        ('option', 'Почему вызов malloc на 1 ГБ может завершиться успешно, хотя свободной оперативной памяти меньше?', 'Ядро сначала выдаёт только адреса, а страницы оперативной памяти обычно выделяет при первой записи в них', NULL, 'Это выделение по требованию. Разрешать ли такие обещания сверх свободной памяти, решает режим overcommit (vm.overcommit_memory).', 'Это выделение по требованию. Допустимость новых обязательств по памяти определяет режим overcommit (vm.overcommit_memory) — отдельный механизм.'),
        ('option', 'У службы systemd заданы MemoryHigh=1700M и MemoryMax=2G, своп для неё не ограничен. Процессу службы нужно 3,6 ГБ. Что произойдёт?', 'Выше 1700 МБ ядро будет притормаживать процесс и вытеснять его страницы в своп, пока там есть место', 'Выше 1700 МБ ядро будет притормаживать процесс и принудительно освобождать его память, в том числе вытеснять страницы в своп, если есть подходящие страницы и место', NULL, NULL),
        ('option', 'У службы systemd заданы MemoryHigh=1700M и MemoryMax=2G, своп для неё не ограничен. Процессу службы нужно 3,6 ГБ. Что произойдёт?', 'Процесс сразу будет завершён по лимиту MemoryMax', NULL, 'Не сразу: MemoryMax ограничивает оперативную память, а излишек уходит в своп. Жёсткий лимит и OOM возможны позже, если вытеснять станет нечего или своп кончится.', 'Не сразу: сначала ядро пытается освободить память, в том числе вытеснением в своп. Жёсткий лимит и OOM возможны позже, если освободить память не удаётся.'),
        ('option', 'У службы systemd заданы MemoryHigh=1700M и MemoryMax=2G, своп для неё не ограничен. Процессу службы нужно 3,6 ГБ. Что произойдёт?', 'Служба будет перезапускаться каждый раз, как процесс займёт 2 ГБ', NULL, 'Мгновенного перезапуска нет: сначала срабатывают мягкий порог и вытеснение в своп.', 'Мгновенного перезапуска нет: сначала срабатывают мягкий порог и освобождение памяти.'),
        ('explanation', 'Какие настройки службы systemd ограничат её оперативную память 2 ГБ и запретят ей своп, чтобы нехватка памяти не превращалась в долгое торможение в свопе?', NULL, NULL, 'Жёсткий лимит без свопа превращает нехватку памяти в заметную ошибку внутри службы, а не в долгое торможение всего сервера. OOMPolicy=continue не даёт systemd остановить всю службу из-за самого OOM-события, но не спасает, если завершён её главный процесс.', 'Настройки запрещают своп этой службе; если освободить память не удаётся, возможен OOM внутри её группы. Какой процесс станет жертвой и как быстро, не гарантируется. OOMPolicy=continue не даёт systemd остановить всю службу из-за самого OOM-события, но не спасает, если завершён её главный процесс.'),
        ('option', 'Какие настройки службы systemd ограничат её оперативную память 2 ГБ и запретят ей своп, чтобы нехватка памяти не превращалась в долгое торможение в свопе?', 'MemoryMax=2G и MemorySwapMax=infinity', NULL, 'Своп службе не ограничен: излишек уйдёт в своп, и процесс будет тормозить.', 'Своп службе разрешён, поэтому эти настройки не выполняют требование запретить своп.'),
        ('option', 'В Linux postmaster породил обслуживающий процесс для нового клиента вызовом fork. Что верно для памяти этого процесса сразу после fork?', 'В его памяти уже есть код и прочитанные postmaster настройки, а физически страницы разделяются с postmaster до первой записи', 'В его памяти уже есть код и прочитанные postmaster настройки; приватные страницы физически разделяются с postmaster до первой записи, а разделяемые отображения остаются общими', 'Так работает копирование при записи: копия страницы появляется, только когда один из процессов в неё пишет.', 'Так работает копирование при записи для приватных страниц: копия появляется, только когда один из процессов в страницу пишет.'),
        ('option', 'В Linux postmaster породил обслуживающий процесс для нового клиента вызовом fork. Что верно для памяти этого процесса сразу после fork?', 'postmaster заново запускает программу postgres через exec и передаёт ей настройки', NULL, 'Так сделано в Windows, где нет fork; в Linux новый процесс получает копию памяти postmaster.', 'В Windows PostgreSQL запускает новый процесс через CreateProcess и передаёт ему нужные параметры; в Linux новый процесс получает копию памяти postmaster через fork.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
